1	import { createApp, inject } from "vue";
2	import { createRouter, createWebHistory } from "vue-router";
3	import { VueQueryPlugin } from "@tanstack/vue-query";
4	import { LocalStorageKey } from "@/lib/constant";
5	import App from "@/App.vue";
6	import "@/assets/index.css";
7	import { jwtDecode } from "jwt-decode";
8	import { JwtToken } from "@/lib/type";
9	
10	const app = createApp(App);
11	app.use(VueQueryPlugin);
12	
13	try {
14	  const jwtToken = localStorage.getItem(LocalStorageKey.JWT_TOKEN);
15	  // Check if the token exists
16	  if (!jwtToken) throw new Error("No JWT token found in local storage");
17	  const user = jwtDecode<JwtToken>(jwtToken);
18	  // Check if the token is expired (allowing a grace period of 8 hours)
19	  if (user?.iat && Math.floor(Date.now() / 1000) - user.iat > 8 * 60 * 60)
20	    throw new Error("Token expired");
21	  app.provide("user", user);
22	} catch (error) {
23	  localStorage.removeItem(LocalStorageKey.JWT_TOKEN);
24	  app.provide("user", null);
25	}
26	
27	const routes = [
28	  { path: "/", component: () => import("@/views/HomeView.vue") },
29	  { path: "/help", component: () => import("@/views/help/HelpPage.vue") },
30	  { path: "/docs", component: () => import("@/views/docs/DocsPage.vue") },
31	  { path: "/login", component: () => import("@/views/login/LoginPage.vue") },
32	  { path: "/rating", component: () => import("@/views/rating/RatingPage.vue") },
33	];
34	
35	const router = createRouter({
36	  history: createWebHistory(),
37	  routes,
38	});
39	
40	router.beforeEach((to) => {
41	  const isAuthenticated = inject("user") !== null;
42	  if (to.path === "/login" && isAuthenticated) return "/";
43	  if (to.path !== "/login" && !isAuthenticated) return "/login";
44	  if (to.path === "/" && isAuthenticated && !to.query.flow) {
45	    return { path: "/", query: { ...to.query, flow: "6" } };
46	  }
47	  return true;
48	});
49	
50	app.use(router).mount("#app");
51

1	<script setup lang="ts">
2	import { ref, provide, computed, inject, watch, type Ref } from "vue";
3	import { Role } from "@/lib/enum";
4	import { toChatBottom } from "@/lib/utils";
5	import { useRoute } from "vue-router";
6	import { useLocalStorage } from "@vueuse/core";
7	import { LocalStorageKey, SIMPLE_MODE_FLOW_IDS } from "@/lib/constant";
8	import { useQASearch } from "@/hooks/useQASearch";
9	import { MessageStatus as Status, type Message, type QAItem } from "@/lib/type";
10	import { callAI, type CallConfig, type AICallContext } from "@/hooks/useAICall";
11	import { compareQAIds, parseContactInfo } from "@/hooks/chatUtils";
12	import {
13	  handleAudioTranscription,
14	  type AudioTranscriptionContext,
15	} from "@/hooks/useAudioTranscription";
16	import { uploadFile } from "@/hooks/useFileUpload";
17	
18	const route = useRoute();
19	const jwtToken = useLocalStorage(LocalStorageKey.JWT_TOKEN, "");
20	
21	const messages = ref<Message[][]>([]);
22	const isTranscribing = ref(false);
23	const isUploading = ref(false);
24	const isPending = computed(() => {
25	  return messages.value.length > 0
26	    ? messages.value.at(-1)?.at(-1)?.status === Status.Pending ||
27	        messages.value.at(-1)?.at(-1)?.status === Status.Receiving
28	    : false;
29	});
30	//const BASE_URL = import.meta.env.VITE_AI_API_URL;
31	const publicKey = import.meta.env.VITE_API_PUBLICKEY;
32	const fingerprint = inject<Ref<string>>("fingerprint");
33	const { searchQA } = useQASearch();
34	
35	// 保存上一次的 QA 結果 id 列表（只存前 5 個）
36	const previousQAIds = ref<number[] | null>(null);
37	
38	// 選擇模式：立即回答(0) 或 搜尋推理(2)
39	const selectedMode = ref<string>("0");
40	
41	// flow=8（未來教室設備支援助理）用：使用者附加照片問問題，送出後清空
42	const attachedImage = ref<{
43	  mimeType: string;
44	  data: string;
45	  previewUrl: string;
46	} | null>(null);
47	
48	function setAttachedImage(file: File) {
49	  return new Promise<void>((resolve, reject) => {
50	    const reader = new FileReader();
51	    reader.onload = () => {
52	      const dataUrl = reader.result as string;
53	      const match = dataUrl.match(/^data:(.+);base64,(.+)$/);
54	      if (!match) {
55	        reject(new Error("無法讀取圖片"));
56	        return;
57	      }
58	      attachedImage.value = {
59	        mimeType: match[1],
60	        data: match[2],
61	        previewUrl: dataUrl,
62	      };
63	      resolve();
64	    };
65	    reader.onerror = () => reject(new Error("無法讀取圖片"));
66	    reader.readAsDataURL(file);
67	  });
68	}
69	
70	function clearAttachedImage() {
71	  attachedImage.value = null;
72	}
73	
74	/**
75	 * flow=7（學習規劃探索助手）的固定開場白，內容需與後端 AdvisingChatService.cs 的
76	 * Stage 1 開場文字保持一致，才能讓後續對話歷史正確反映「已經自我介紹過」。
77	 * 進入頁面就直接顯示，不需要使用者輸入「開始」才觸發。
78	 */
79	const ADVISING_OPENING_MESSAGE =
80	  "你好，我是臺大學習規劃辦公室的 AI 學習探索助手。\n" +
81	  "在你正式和學習規劃師會談前，我會陪你先整理目前的想法，讓之後的會談更有效率。\n\n" +
82	  "你最近想和學習規劃師聊什麼學習議題呢？\n" +
83	  "可以是課業、選課、生涯探索、時間管理、學習動力，或任何和學習有關的事情。";
84	
85	/**
86	 * flow=8（未來教室設備支援助理）的固定開場白，內容需與後端 ClassroomFaqChatService.cs 的
87	 * 「身分辨識」段落保持一致，讓後續對話歷史正確反映「已經問過身分」，模型才能依身分分流回答。
88	 * 進入頁面就直接顯示，不需要使用者輸入才觸發。
89	 */
90	const CLASSROOM_FAQ_OPENING_MESSAGE =
91	  "您好！歡迎使用未來教室 AI 助手 👋\n" +
92	  "無論是設備操作、教室使用或其他相關問題，都可以問我。\n" +
93	  "為了提供更精準的協助，請先選擇您的身分：老師／課程助教／學生　｜　數位學習中心人員／教室助教";
94	
95	// 用 watch + immediate 而非 onMounted：ChatProvider 包在 <RouterView> 外層，只在整個 App
96	// 掛載時 mount 一次；此時 vue-router 的初始導航（含 beforeEach 對 flow 的處理）可能還沒解析完成，
97	// route.query.flow 會是空的，onMounted 會撲空。改用 watch 才能在 flow 真正變成 "7"/"8" 時觸發。
98	watch(
99	  () => route.query.flow,
100	  (flow) => {
101	    if (messages.value.length !== 0) return;
102	
103	    const flowValue = flow?.toString();
104	    let openingMessage: string | null = null;
105	    if (flowValue === "7") {
106	      openingMessage = ADVISING_OPENING_MESSAGE;
107	    } else if (flowValue === "8") {
108	      openingMessage = CLASSROOM_FAQ_OPENING_MESSAGE;
109	    }
110	
111	    if (openingMessage) {
112	      messages.value.push([
113	        {
114	          role: Role.Assistant,
115	          content: openingMessage,
116	          timestamp: Date.now(),
117	          status: Status.End,
118	        },
119	      ]);
120	    }
121	  },
122	  { immediate: true },
123	);
124	
125	// const flowMap = new Map([
126	//   ["9ed73cfca07e0977e88f0c81e6429dac", "0"], // wayne
127	//   ["1326a2c799069509f09edc2de765367b", "0"], // 課務組 (綜合)
128	//   ["efb3c7cf7cce5e000159bbb250fbc142", "0"], // 研教組
129	//   ["d42963cbe4e959d8264cbd565d1504a3", "1"], // 課務組 (博雅) (重灌)
130	//   ["f00e6d14be4cc615d0a9fb74e2785fd0", "1"], // 課務組 (博雅)
131	//   ["bf2012eee60e491adfb4b12e076718ec", "1"], // 註冊組
132	//   ["3105d7609f6df5ec44b96c9690019a60", "1"], // 醫教分處
133	//   ["325df44fb860d37044bcdaa8296533a9", "1"], // 醫教分處,2
134	// ]);
135	
136	async function handleAudioTranscriptionWrapper(audioBlob: Blob) {
137	  const context: AudioTranscriptionContext = {
138	    publicKey,
139	    fingerprint,
140	    jwtToken,
141	    isTranscribing,
142	  };
143	  return handleAudioTranscription(context, audioBlob);
144	}
145	
146	/**
147	 * 上傳文件到 flowId=6 的個人知識庫，上傳狀態透過聊天訊息呈現
148	 */
149	async function handleFileUploadWrapper(file: File) {
150	  const messageIndex = addUserMessage(`📎 上傳文件：${file.name}`);
151	  messages.value[messageIndex][1] = {
152	    role: Role.Assistant,
153	    content: "文件上傳中",
154	    timestamp: Date.now(),
155	    status: Status.Pending,
156	  };
157	  toChatBottom({ behavior: "smooth" });
158	
159	  isUploading.value = true;
160	  try {
161	    const resultMessage = await uploadFile({ jwtToken }, file);
162	    messages.value[messageIndex][1] = {
163	      role: Role.Assistant,
164	      content: resultMessage,
165	      timestamp: Date.now(),
166	      status: Status.End,
167	    };
168	  } catch (error) {
169	    console.error(error);
170	    messages.value[messageIndex][1] = {
171	      role: Role.Assistant,
172	      content: `文件上傳失敗：${error instanceof Error ? error.message : "請稍後再試"}`,
173	      timestamp: Date.now(),
174	      status: Status.Error,
175	    };
176	  } finally {
177	    isUploading.value = false;
178	    toChatBottom({ behavior: "smooth" });
179	  }
180	}
181	
182	// ==================== 使用者訊息創建 ====================
183	
184	function addUserMessage(content: string): number {
185	  const timestamp = Date.now();
186	  const length = messages.value.length;
187	
188	  messages.value.push([]);
189	  messages.value[length][0] = {
190	    role: Role.User,
191	    content,
192	    timestamp,
193	    status: Status.User,
194	  };
195	  toChatBottom({ behavior: "smooth" });
196	
197	  return length;
198	}
199	
200	// ==================== 主要流程 ====================
201	
202	async function send(content: string, flowId?: string) {
203	  // 1. 創建用戶消息（附加照片時在訊息內容加註提示，讓歷史紀錄也看得出來曾經附圖）
204	  const pendingImage = attachedImage.value ?? undefined;
205	  const displayContent = pendingImage ? `${content}\n📎 已附加照片` : content;
206	  const messageIndex = addUserMessage(displayContent);
207	  clearAttachedImage();
208	
209	  // flow=3（簡易模式）或 flow=6（Gemini File Search RAG）時，跳過 QA 搜尋，直接呼叫 AI
210	  const routeFlow = route.query.flow?.toString();
211	  if (routeFlow && SIMPLE_MODE_FLOW_IDS.includes(routeFlow)) {
212	    await callAIWrapper(messageIndex, content, routeFlow, undefined, pendingImage);
213	    return;
214	  }
215	
216	  // 2. 搜索 QA
217	  const qaResults = await searchQA(content);
218	  // 3. 處理 QA 結果
219	  const shouldShowQAList = handleQAResults(qaResults, messageIndex, content);
220	  if (shouldShowQAList) return; // 顯示 QA 列表，結束流程
221	  // 4. 調用 AI
222	  await callAIWrapper(messageIndex, content, flowId, undefined, pendingImage);
223	}
224	
225	/**
226	 * 處理 QA 搜尋結果
227	 * @returns true 如果顯示了 QA 列表，false 如果應該繼續調用 AI
228	 */
229	function handleQAResults(
230	  qaResults: QAItem[] | null,
231	  messageIndex: number,
232	  originalContent: string,
233	): boolean {
234	  // 沒有 QA 結果，清空記錄並繼續呼叫 AI
235	  if (!qaResults || qaResults.length === 0) {
236	    previousQAIds.value = null;
237	    return false;
238	  }
239	
240	  const limitedResults = qaResults.slice(0, 5);
241	  const currentIds = limitedResults
242	    .map((item) => item.id)
243	    .filter((id): id is number => id !== undefined);
244	
245	  // 如果這次的 QA 結果和上次一樣，改用 AI 回覆
246	  if (
247	    previousQAIds.value &&
248	    currentIds.length > 0 &&
249	    compareQAIds(currentIds, previousQAIds.value)
250	  ) {
251	    // 結果相同，不更新 previousQAIds，繼續呼叫 AI
252	    return false;
253	  }
254	
255	  // 結果不同或沒有上一次結果，顯示 QA 清單
256	  previousQAIds.value = currentIds.length > 0 ? currentIds : null;
257	
258	  messages.value[messageIndex][1] = {
259	    role: Role.Assistant,
260	    content: "吉吉鳥猜你是想要問",
261	    timestamp: Date.now(),
262	    status: Status.End,
263	    qa: limitedResults,
264	    question: originalContent,
265	  };
266	
267	  toChatBottom({ behavior: "smooth" });
268	  return true;
269	}
270	
271	/**
272	 * 顯示查詢方式選擇，用於"都不是我要問的，重新查詢"按鈕
273	 */
274	function showQueryModeSelection(question: string) {
275	  const messageIndex = addUserMessage("都不是我要問的，重新查詢");
276	
277	  // 顯示系統消息
278	  messages.value[messageIndex][1] = {
279	    role: Role.Assistant,
280	    content: "你想用哪種方式查詢呢？",
281	    timestamp: Date.now(),
282	    status: Status.End,
283	    question,
284	  };
285	  toChatBottom({ behavior: "smooth" });
286	}
287	
288	/**
289	 * 根據選擇的查詢方式呼叫 AI
290	 */
291	async function sendMessageToAIWithMode(
292	  content: string,
293	  flowId: string,
294	  displayContent?: string,
295	) {
296	  const messageIndex = addUserMessage(displayContent || content);
297	  await callAIWrapper(
298	    messageIndex,
299	    content,
300	    flowId,
301	    "吉吉鳥正在搜尋其他可能的答案",
302	  );
303	}
304	
305	/**
306	 * 顯示 QA 直接答案
307	 * 用於點擊 QA 列表中的問題
308	 */
309	async function showQADirectAnswer(qa: QAItem) {
310	  const userContent =
311	    qa.type === "organizer"
312	      ? `給我以下問題的承辦單位：${qa.question}`
313	      : qa.question;
314	  const messageIndex = addUserMessage(userContent);
315	
316	  // 顯示載入中
317	  messages.value[messageIndex][1] = {
318	    role: Role.Assistant,
319	    content: "吉吉鳥正在尋找答案中",
320	    timestamp: Date.now(),
321	    status: Status.Pending,
322	  };
323	  toChatBottom({ behavior: "smooth" });
324	
325	  // 模擬載入時間
326	  await new Promise((resolve) => setTimeout(resolve, 500));
327	
328	  // 顯示答案
329	  const contact = parseContactInfo(qa.tel, qa.email, qa.answer);
330	
331	  messages.value[messageIndex][1] = {
332	    role: Role.Assistant,
333	    content:
334	      contact.length > 0 ? "如需進一步，協助請聯絡以下負責單位" : qa.answer,
335	    timestamp: Date.now(),
336	    status: Status.End,
337	    contact: contact.length > 0 ? contact : undefined,
338	  };
339	
340	  toChatBottom({ behavior: "smooth" });
341	}
342	
343	// ==================== AI 調用 ====================
344	
345	/**
346	 * flowId=7（學習規劃探索助手）、flowId=8（未來教室設備支援助理）共用：
347	 * 把目前這一輪之前的完整對話紀錄轉成 Gemini 的 user/model 格式，讓後端組成多輪 contents 陣列，
348	 * 模型才能依對話紀錄自行判斷目前進度、延續前面討論的內容。
349	 */
350	function buildChatHistory(): { role: "user" | "model"; text: string }[] {
351	  return messages.value.slice(0, -1).flatMap((pair) =>
352	    pair
353	      .filter(
354	        (m) =>
355	          (m.role === Role.User || m.role === Role.Assistant) &&
356	          m.status !== Status.Error,
357	      )
358	      .map((m) => ({
359	        role: m.role === Role.User ? ("user" as const) : ("model" as const),
360	        text: m.content,
361	      })),
362	  );
363	}
364	
365	const HISTORY_FLOW_IDS = new Set(["7", "8"]);
366	
367	/**
368	 * 呼叫 AI，根據 flow 設定處理
369	 */
370	async function callAIWrapper(
371	  messageIndex: number,
372	  content: string,
373	  flowId?: string,
374	  loadingText?: string,
375	  image?: { mimeType: string; data: string },
376	) {
377	  const context: AICallContext = {
378	    messages,
379	    publicKey,
380	    fingerprint,
381	    jwtToken,
382	    route,
383	  };
384	
385	  // flow=7（學習規劃探索助手）用：網址帶 ?model=openai / ?model=claude 切換供應商，預設 gemini
386	  const modelParam = route.query.model?.toString();
387	
388	  // 1. 優先使用 route.query.flow（用於測試等場景）
389	  if (route.query.flow) {
390	    const flowIds = route.query.flow.toString().split(",");
391	    for (let index = 0; index < flowIds.length; index++) {
392	      const id = flowIds[index];
393	      const config: CallConfig = {
394	        content,
395	        flowId: id,
396	        loadingText,
397	        ...(HISTORY_FLOW_IDS.has(id) ? { history: buildChatHistory() } : {}),
398	        ...(image ? { image } : {}),
399	        ...(modelParam ? { model: modelParam } : {}),
400	      };
401	      await callAI(context, messageIndex, 1, config, id === "0");
402	    }
403	    return;
404	  }
405	
406	  // 2. 使用傳入的 flowId，或默認使用 "0"
407	  const finalFlowId = flowId || "0";
408	  const config: CallConfig = {
409	    content,
410	    flowId: finalFlowId,
411	    loadingText,
412	    ...(HISTORY_FLOW_IDS.has(finalFlowId)
413	      ? { history: buildChatHistory() }
414	      : {}),
415	    ...(image ? { image } : {}),
416	    ...(modelParam ? { model: modelParam } : {}),
417	  };
418	  await callAI(context, messageIndex, 1, config, finalFlowId === "0");
419	}
420	
421	provide("messages", messages);
422	provide("isPending", isPending);
423	provide("isTranscribing", isTranscribing);
424	provide("isUploading", isUploading);
425	provide("send", send);
426	provide("sendDirectAnswer", showQADirectAnswer);
427	provide("sendDirectToAI", showQueryModeSelection);
428	provide("sendMessageToAIWithMode", sendMessageToAIWithMode);
429	provide("handleAudioTranscription", handleAudioTranscriptionWrapper);
430	provide("handleFileUpload", handleFileUploadWrapper);
431	provide("selectedMode", selectedMode);
432	provide("attachedImage", attachedImage);
433	provide("setAttachedImage", setAttachedImage);
434	provide("clearAttachedImage", clearAttachedImage);
435	</script>
436	
437	<template>
438	  <slot />
439	</template>
