1	export const SCROLL_ID = "ntu-scroll";
2	
3	/**
4	 * 這些 flow 直接進 AI 對話，不顯示快速常見問答、不跑 QA 資料庫搜尋。
5	 * 3 = 簡易模式；6 = Gemini File Search RAG（個人文件問答）；7 = 學習規劃探索助手（Gemini 多輪對話）；
6	 * 8 = 未來教室設備支援助理（Gemini 多輪對話，可附加照片問問題）。
7	 */
8	export const SIMPLE_MODE_FLOW_IDS = ["3", "6", "7", "8"];
9	
10	export const NPS_ENDPOINT =
11	  "https://script.google.com/macros/s/AKfycbzZEF0pLOc2puEz8nsAaAqaRr79aOIxh2lSY8JYuahqp9opeuM5Qti93mT20LnAjOiq/exec";
12	
13	export enum LocalStorageKey {
14	  JWT_TOKEN = "auth.jwt_token",
15	  POLICY_ACCEPTED = "app.policy_accepted",
16	}
17	
18	export enum TokenKey {
19	  CHINESE_NAME = "http://www.ntu.edu.tw/ChineseName",
20	  ACCOUNT_NAME = "http://www.ntu.edu.tw/AccountName",
21	  ACCOUNT_TYPE = "http://www.ntu.edu.tw/AccountTypeCode",
