15	    public class AdvisingChatService : IAdvisingChatService
16	    {
17	        private readonly IHttpClientFactory _httpClientFactory;
18	        private readonly AppSettingConfig _appSetting;
19	        private readonly ILogger<AdvisingChatService> _logger;
20	
21	        public AdvisingChatService(
22	            IHttpClientFactory httpClientFactory,
23	            AppSettingConfig appSetting,
24	            ILogger<AdvisingChatService> logger)
25	        {
26	            _httpClientFactory = httpClientFactory;
27	            _appSetting = appSetting;
