31	        private HttpClient CreateGeminiClient()
32	        {
33	            var client = _httpClientFactory.CreateClient("Gemini");
34	            client.DefaultRequestHeaders.Remove("x-goog-api-key");
35	            client.DefaultRequestHeaders.Add("x-goog-api-key", _appSetting.AdvisingGeminiApiKey);
