140	
141	            Response.ContentType = "text/event-stream";
142	            Response.Headers.Append("Cache-Control", "no-cache");
143	            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");
144	
145	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
146	            {
147	                var payload = JsonSerializer.Serialize(new
148	                {
149	                    delta = chunk.Delta,
150	                    source = chunk.Source,

145	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
146	            {
147	                var payload = JsonSerializer.Serialize(new
148	                {
149	                    delta = chunk.Delta,
150	                    source = chunk.Source,
151	                    done = chunk.Done,
