165	        private async Task<IActionResult> RunAdvisingFlow(JsonElement body)
166	        {
167	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
168	            if (string.IsNullOrEmpty(userId))
169	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
170	
171	            if (!body.TryGetProperty("input_value", out var inputValueEl))
